import numpy as np; import pandas as pd; from sentence_transformers import SentenceTransformer; from sklearn.metrics.pairwise import cosine_similarity; a=pd.read_csv("data/processed/articles_with_embeddings.csv"); e=np.load("data/processed/article_embeddings.npy"); m=SentenceTransformer("all-MiniLM-L6-v2"); q=input("Enter your AI news question: ").strip(); s=cosine_similarity(m.encode([q]),e)[0] if q else []; idx=np.argsort(s)[::-1][:5] if q else []; [print("\nTitle:",a.iloc[i]["title"],"\nSource:",a.iloc[i]["source"],"\nScore:",round(float(s[i]),3),"\nURL:",a.iloc[i]["url"],"\nContent:",str(a.iloc[i]["content"])[:400],"\n"+"-"*50) for i in idx] if q else print("Please enter a question.")
